import { parseArgs } from "node:util";
import { TuituiBotClient } from "@qihoo/tuitui-bot-sdk";
import { loadSampleConfig } from "./config.js";

function parseTo(client: TuituiBotClient) {
  const { values } = parseArgs({
    options: {
      account: { type: "string" },
      uid: { type: "string" },
      group: { type: "string" },
    },
  });

  if (values.account && !values.uid && !values.group) {
    return client.to.account(values.account);
  }
  if (values.uid && !values.account && !values.group) {
    return client.to.uid(values.uid);
  }
  if (values.group && !values.account && !values.uid) {
    return client.to.group(values.group);
  }

  console.error(
    "用法: npm run sample:send-text -- --account <账号> | --uid <UID> | --group <群ID>",
  );
  process.exit(1);
}

const config = loadSampleConfig();
const client = new TuituiBotClient(config.appId, config.appSecret);

try {
  const response = await client.im.sendText({
    to: parseTo(client),
    text: "你好，来自 `ts` SDK",
  });

  console.log("消息发送成功", response);
} catch (error) {
  // 发送失败需要记录日志，方便后面排查问题。
  console.error("消息发送失败", error);
}
